"""Post-evaluation paired error transitions; never feed diagnostics into fitting."""
from pathlib import Path
import pandas as pd
import numpy as np
from dlpro.experiment_core import LENGTH,save_json
out=Path('results/performance_validation');known=pd.read_csv('data/processed/known_windows.csv');f=pd.read_csv('results/classification_repeat_ssl/out_of_fold_predictions.csv');old=pd.read_csv('results/classification_fine/out_of_fold_predictions.csv');old=old[old.recipe=='fine_consistent_ensemble'].set_index('structure_id');rows=known[['structure_id','type','center','group']].copy();rows['baseline_prediction']=old.loc[rows.structure_id,'predicted_type'].to_numpy()
for recipe in f.recipe.unique():rows[recipe]=f[f.recipe==recipe].set_index('structure_id').loc[rows.structure_id,'predicted_type'].to_numpy()
chin=known[known.type=='CHIN'].center.to_numpy();d=abs(rows.center.to_numpy()[:,None]-chin[None]);rows['nearest_chin_center_bp']=np.minimum(d,LENGTH-d).min(1);rows['baseline_correct']=rows.type==rows.baseline_prediction;rows['selected_correct']=rows.type==rows.validation_selected;rows['transition']=np.where(rows.baseline_correct, np.where(rows.selected_correct,'both_correct','regressed'),np.where(rows.selected_correct,'corrected','both_wrong'));rows.to_csv(out/'classification_error_transitions.csv',index=False);rows.groupby(['type','transition']).size().rename('n_loci').reset_index().to_csv(out/'classification_transitions_by_type.csv',index=False)
chid=rows[rows.type=='CHID'].copy();chid['nested_distance_stratum']=pd.cut(chid.nearest_chin_center_bp,[-1,500,2000,float('inf')],labels=['0-500bp','501-2000bp','>2000bp']);summary=chid.groupby('nested_distance_stratum',observed=False).agg(n_loci=('structure_id','size'),baseline_recalled=('baseline_correct','sum'),selected_recalled=('selected_correct','sum'));summary.to_csv(out/'chid_distance_diagnostic.csv');save_json(out/'error_analysis_protocol.json',dict(unit='Same344 OOF loci; paired predictions,26CHID subset',geometry='NearestCHINcenter circular distance used only after evaluation for error diagnosis, never as model input',limitations=['Retrospective diagnostic, not a new model-selection signal','Nested biological structures can retain distinct course labels','Small strata do not establish a causal reason for errors']))
print(rows.groupby(['type','transition']).size().to_string(),flush=True)
